duct-card;\n}\n","/* stylelint-disable */\n/* stylelint-disable */\n.section-products {\n  padding-bottom: var(--default-padding);\n}\n.section-products__wrapp {\n  display: flex;\n  flex-direction: column;\n  gap: var(--default-gap);\n}\n.section-products__wrapp > .main-button {\n  align-self: center;\n}\n@media (max-width: 575px) {\n  .section-products__wrapp > .main-button {\n    width: 100%;\n  }\n}\n.section-products__top {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n  justify-content: space-between;\n}\n.section-products__title {\n  font-family: var(--third-family);\n  font-weight: 600;\n  font-size: clamp(22px, 2.7778vw, 40px);\n  line-height: 130%;\n  text-transform: uppercase;\n  color: var(--neutral-600);\n}\n.section-products .products-slider {\n  width: 100%;\n  overflow: hidden;\n}\n.section-products .products-slider .swiper-container {\n  width: 100%;\n}\n@media (max-width: 1024px) {\n  .section-products .products-slider .swiper-container {\n    padding: 0 var(--container-offset);\n  }\n}\n.section-products .products-slider .swiper-slide {\n  height: 100%;\n  display: flex;\n}\n@media (max-width: 1024px) {\n  .section-products .products-slider {\n    width: calc(100% + var(--container-offset) * 2);\n    margin-left: calc(var(--container-offset) * -1);\n  }\n}\n.section-products .product-card {\n  padding: var(--gap);\n  display: flex;\n  flex-direction: column;\n  gap: clamp(16px, 2.2222vw, 32px);\n  border: 1px solid var(--neutral-200);\n  height: clamp(521px, 63.09vw, 646px);\n}\n.section-products .product-card__thumb {\n  display: flex;\n  align-items: center;\n  height: clamp(300px, 34.18vw, 350px);\n  justify-content: center;\n  overflow: hidden;\n  flex-shrink: 0;\n  background: rgba(242, 243, 242, 0.5);\n}\n.section-products .product-card__thumb img,\n.section-products .product-card__thumb picture {\n  transition: all 0.3s;\n  height: 100%;\n  width: auto;\n}\n.section-products .product-card__body {\n  display: flex;\n  flex-directi